{
  "technical_and_design_decisions": [
    "Port each XD module (json-to-tuple, object-to-json, script, shell, splitter) as a standalone Spring Boot application built on Spring Cloud Stream, using the @EnableBinding(Processor.class) programming model instead of the legacy XD module model.",
    "Use Java 17 as the language baseline with Spring Framework 6 / Spring Boot 3, consistent with the framework requirements stated in the specification.",
    "Organize the s-c-s repository as a multi-module Maven build, with one module per processor plus a shared common module for reusable utilities (JSON handling, expression support, configuration metadata).",
    "Implement the BinderFactory abstraction (U8) as a Spring Boot auto-configured factory with binder implementations registered via classpath scanning/ServiceLoader-style registration, enabling pluggable binder types (e.g., Kafka, RabbitMQ) without changes to processor code.",
    "Reuse the existing Spring XD module business logic where feasible, refactoring it to Spring Boot externalized configuration (@ConfigurationProperties) and Spring Cloud Stream functional interfaces rather than rewriting from scratch.",
    "Treat U6 and U7 as time-boxed exploration spikes: deliverables are a written analysis of options plus a minimal proof-of-concept prototype, not production-hardened implementations.",
    "Use the Curator framework over Apache ZooKeeper for the composed-job-definition persistence spike (U7).",
    "Adopt JUnit 5 with Spring Boot Test and Testcontainers (or embedded brokers) for unit and integration testing of all modules."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are effort (workdays), not elapsed calendar time.",
    "The original Spring XD source code for the five modules is available and its logic can be legally and technically reused in the s-c-s repo.",
    "The s-c-s repository, build infrastructure, and CI pipeline already exist; only module-level setup is required.",
    "U6 and U7 are exploration/spike stories only; production implementation of composed job removal or ZK persistence is out of scope for this increment.",
    "Test instances of supported binders (e.g., embedded Kafka/RabbitMQ or Testcontainers) and a ZooKeeper ensemble are available for testing and prototyping.",
    "Estimates include unit tests, integration tests, code review/rework, and developer-level documentation; no dedicated QA or technical writing staff is involved.",
    "No major upstream API breaking changes occur in Spring Cloud Stream or Spring Boot during the increment."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and overall technical design",
      "activity_description": "Analyze the eight user stories, review the legacy Spring XD module implementations, define the target Spring Cloud Stream processor architecture, configuration property conventions, and the BinderFactory abstraction design (covers U1-U8).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Repository and build scaffolding",
      "activity_description": "Set up the multi-module Maven structure in the s-c-s repo, parent POM, dependency management (Spring Boot 3 / Spring Cloud Stream), common shared module, and CI build wiring for the new processor modules.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "U8: BinderFactory abstraction design and implementation",
      "activity_description": "Design and implement the BinderFactory abstraction including factory interfaces, auto-configuration, binder registration mechanism, default binder wiring, unit tests, and integration tests validating multiple binder types can be plugged in.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "U1: Port json-to-tuple processor module",
      "activity_description": "Port the json-to-tuple module from XD to a Spring Cloud Stream processor: adapt code to the processor binding model, externalize configuration, write unit and integration tests, and update module documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "U2: Port object-to-json processor module",
      "activity_description": "Port the object-to-json module from XD to a Spring Cloud Stream processor: adapt serialization logic and configuration, write unit and integration tests, and update module documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "U3: Port script processor module",
      "activity_description": "Port the script module from XD to a Spring Cloud Stream processor: adapt JSR-223 scripting engine integration, script location/refresh configuration, security considerations, unit and integration tests, and documentation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A7",
      "activity_name": "U4: Port shell processor module",
      "activity_description": "Port the shell module from XD to a Spring Cloud Stream processor: adapt external process execution, working directory/environment configuration, stdout/stderr and error handling, timeouts, unit and integration tests, and documentation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A8",
      "activity_name": "U5: Port splitter processor module",
      "activity_description": "Port the splitter module from XD to a Spring Cloud Stream processor: adapt splitting/expression logic to the processor binding model, externalize configuration, write unit and integration tests, and update documentation.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "U6: Spike - explore options to remove composed job",
      "activity_description": "Time-boxed exploration of approaches to remove the composed job concept, analyzing resource usage and memory footprint implications; produce a comparison of options, a small prototype where needed, and a recommendation report.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "U7: Spike - persist composed job definition in ZooKeeper metadata",
      "activity_description": "Time-boxed exploration of storing composed job definitions as ZooKeeper metadata (using Curator) so jobs can be recreated for failure recovery; build a proof-of-concept prototype, evaluate failure scenarios, and document findings and recommendations.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A11",
      "activity_name": "End-to-end integration testing",
      "activity_description": "Verify all five ported processors in representative streaming pipelines (source -> processor -> sink) against real or containerized binders, validate BinderFactory-driven binder switching, and fix defects found.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation and usage samples",
      "activity_description": "Write reference documentation for each ported processor (properties, usage examples), the BinderFactory abstraction, and spike outcome summaries for U6 and U7.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "Code review and rework",
      "activity_description": "Self-review and rework of all ported modules and the BinderFactory abstraction for code quality, consistency of configuration conventions, test coverage gaps, and adherence to Spring Cloud Stream best practices.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 54
  }
}
